declare(strict_types=1);
namespace OCA\Mcp\Tests\Integration\Mail;
use OCA\Mcp\Tests\Integration\IntegrationTestCase;
use PHPUnit\Framework\Attributes\Group;
#[Group('mail')]
final class McpMailDeliveryTest extends IntegrationTestCase {
    private function proof(string $scenario,array $extra=[]):array {
        if(getenv('MCP_IT_WITH_MAIL')!=='1'||getenv('MCP_IT_MAIL_GUARD')!=='1')self::markTestSkipped('Qualified native delivery fixture only.');
        $r=MailActor::run(MailActor::ALICE,'delivery-native',['scenario'=>$scenario]+$extra);if(isset($r['fixture_error']))self::fail(json_encode($r));self::assertTrue($r['implementation_available'],'Native immutable delivery is required.');return $r;
    }
    public static function cancellationRevocations():array {return ['scope'=>['scope'],'tool'=>['tool'],'actor'=>['actor'],'precommit rollback'=>['commit']];}
    #[\PHPUnit\Framework\Attributes\DataProvider('cancellationRevocations')]
    public function testPublicCancellationRevocationInsideNativeOwnerPreservesQueueAndHold(string $mode):void {
        $r=$this->proof('mcp_cancel_'.$mode);self::assertSame('queued',$r['status']);self::assertTrue($r['changed']);self::assertSame('queued',$r['state']);self::assertTrue($r['held']);self::assertSame(0,$r['cancelled_transitions']);self::assertTrue($r['refused']);self::assertTrue($r['smtp_unchanged']);if($mode==='commit')self::assertSame(3,$r['checks']);
    }
    public function testSavedScopeRevocationStopsSignedChildAndOffGateFutureAuditAndHidesOriginalReceipts():void {
        foreach(['mcp_scope_revoked','mcp_future_scope_revoked'] as $mode){$r=$this->proof($mode);self::assertSame('blocked',$r['native_state'],$mode);self::assertFalse($r['has_unresolved']);self::assertTrue($r['scope_status_denied']);self::assertTrue($r['scope_replay_denied']);self::assertTrue($r['smtp_unchanged']);if($mode==='mcp_scope_revoked')self::assertSame('refused',$r['child']);else self::assertTrue($r['gate_off']);}
    }
    public function testActualValidDueOffGateAuditPreservesConsentWithoutReadingPayload():void {$r=$this->proof('mcp_due_paused');self::assertTrue($r['gate_off']);self::assertSame('queued',$r['native_state']);self::assertTrue($r['has_unresolved']);self::assertTrue($r['source_held']);self::assertTrue($r['audit_metadata_only']);self::assertTrue($r['smtp_unchanged']);}
    public function testActualValidFutureOffGateAuditPreservesConsentWithoutReadingPayload():void {$r=$this->proof('mcp_future_paused');self::assertTrue($r['gate_off']);self::assertSame('queued',$r['native_state']);self::assertTrue($r['has_unresolved']);self::assertTrue($r['source_held']);self::assertTrue($r['audit_metadata_only']);self::assertTrue($r['smtp_unchanged']);}
    public function testActualPerUserMailDisableIsTerminalEvenAfterReenable():void {$r=$this->proof('mcp_mail_revoked');self::assertTrue($r['mail_disabled_for_owner']);self::assertTrue($r['mail_enabled_for_other']);self::assertSame('blocked',$r['native_state']);self::assertFalse($r['has_unresolved']);self::assertFalse($r['source_held']);self::assertSame('blocked',$r['restored_state']);self::assertTrue($r['audit_metadata_only']);self::assertTrue($r['smtp_unchanged']);}
    public function testActualFutureRevokedConsentIsAuditedWithTransmissionOffAndNoTransport():void {$r=$this->proof('mcp_future_revoked');self::assertSame('queued',$r['status']);self::assertTrue($r['gate_off']);self::assertTrue($r['audit_index']);self::assertSame('blocked',$r['native_state']);self::assertFalse($r['has_unresolved']);self::assertTrue($r['smtp_unchanged']);}
    public function testActualOperationReadRecoversLostQueueAcknowledgementWithoutResubmission():void {$r=$this->proof('mcp_lost_ack');self::assertTrue($r['recovered']);self::assertSame('queued',$r['state']);self::assertTrue($r['replayed']);self::assertTrue($r['source_revoked_read']);self::assertTrue($r['private']);}
    public function testActualSentRepairToolUsesTheSignedImapOnlyChild():void {$r=$this->proof('mcp_repair');self::assertSame('pending',$r['before']);self::assertSame('verified',$r['after']);self::assertSame('accepted',$r['state']);self::assertTrue($r['replayed']);self::assertSame('mail_send',$r['source_tool']);}
    public function testActualToolsScheduleCancelAndDenyRevokedSourceReplay():void {$r=$this->proof('mcp_schedule');self::assertTrue($r['basic_refused']);self::assertSame('succeeded',$r['admission']);self::assertTrue($r['replayed']);self::assertTrue($r['delivery_id_preserved']);self::assertSame('queued',$r['status']);self::assertSame('cancelled',$r['cancelled']);self::assertTrue($r['source_revoked_read']);self::assertTrue($r['source_revoked_replay']);}
    public function testActualSendToolAndSignedChildProduceNativeAcceptanceEvidence():void {$r=$this->proof('mcp_send');self::assertSame('succeeded',$r['admission']);self::assertTrue($r['replayed']);self::assertSame('completed',$r['child']);self::assertSame('accepted',$r['native_state']);self::assertSame('verified',$r['sent_state']);}
    public function testActualChildReloadsRevokedOriginalConnectionSelection():void {$r=$this->proof('mcp_revoked');self::assertSame('refused',$r['child']);self::assertSame('blocked',$r['native_state']);}
    public function testUnavailableAuthorizationBeforeClaimPreservesQueuedConsentAndHolds():void {$r=$this->proof('unavailable');self::assertSame('queued',$r['state']);self::assertTrue($r['source_mutation_refused']);self::assertTrue($r['has_unresolved']);self::assertSame(0,$r['connections']);}
    public function testProvenBeforeWireBlockAllowsOwnerRecoveryWhileUncertainSmtpRemainsHeld():void {$r=$this->proof('revoked');self::assertSame('blocked',$r['state']);self::assertFalse($r['source_mutation_refused']);self::assertFalse($r['has_unresolved']);self::assertSame(0,$r['connections']);$u=$this->proof('protocol',['mode'=>'ack_lost']);self::assertSame('uncertain',$u['state']);self::assertTrue($u['source_mutation_refused']);self::assertTrue($u['has_unresolved']);}
    public function testChangedInitialSentTargetLeavesAcceptancePendingForSeparateRepair():void {$r=$this->proof('automatic_target_changed');self::assertSame('accepted',$r['state']);self::assertSame('pending',$r['sent_state']);self::assertSame(1,$r['smtp_submissions']);self::assertTrue($r['replay_no_connection']);}
    public function testInitialApprovalBindsAndVerifiesTheNormalSentCopy():void {$r=$this->proof('automatic_sent');self::assertSame('accepted',$r['state']);self::assertSame('verified',$r['sent_state']);self::assertSame(1,$r['smtp_submissions']);self::assertTrue($r['replay_no_connection']);}
    public function testAdmissionIsIdempotentPrivateAndProtectsEveryNativeSourcePath():void {$r=$this->proof('admission');foreach(['idempotent','opaque','receipt_private','operation_mismatch_refused','foreign_status_refused','released','smtp_unchanged'] as $key)self::assertTrue($r[$key],$key);foreach($r['holds'] as $key=>$held)self::assertTrue($held,$key);self::assertSame('cancelled',$r['cancelled']);}
    public function testChangedOrMissingAliasRefusesBeforeAdmission():void {$r=$this->proof('stale');self::assertTrue($r['changed_sender_refused']);self::assertTrue($r['missing_sender_refused']);self::assertTrue($r['smtp_unchanged']);}
    public function testMissingAttachmentCannotBeSilentlyOmitted():void {$r=$this->proof('missing_attachment');self::assertTrue($r['missing_attachment_refused']);self::assertTrue($r['smtp_unchanged']);}
    public function testDisabledGateCannotCreateLatentApproval():void {$r=$this->proof('disabled');self::assertTrue($r['disabled_refused']);self::assertSame([],$r['due']);self::assertTrue($r['smtp_unchanged']);}
    public function testCrashedAttemptNeverConstructsAnotherTransport():void {$r=$this->proof('crash');self::assertSame('uncertain',$r['state']);self::assertSame(0,$r['connections']);self::assertTrue($r['cancel_too_late']);}
    public function testRevokedCurrentFenceBlocksBeforeTransport():void {$r=$this->proof('revoked');self::assertSame('blocked',$r['state']);self::assertSame(0,$r['connections']);}
    public function testRawTlsAdapterPreservesFrozenBytesInBothPipeliningModes():void {foreach([false,true] as $pipeline){$r=$this->proof('protocol',['mode'=>'accept','pipelining'=>$pipeline]);self::assertSame('accepted',$r['state']);self::assertSame('pending',$r['sent_state']);self::assertSame(1,$r['smtp_submissions']);self::assertTrue($r['exact_wire_bytes']);self::assertTrue($r['bcc_private']);self::assertTrue($r['cancel_too_late']);}}
    public function testProtocolFaultsAreTerminalAndNeverResubmitEnvelope():void {foreach(['reject_rcpt','reject_data','disconnect_data','ack_lost','timeout_data'] as $mode){$r=$this->proof('protocol',['mode'=>$mode]);self::assertSame('uncertain',$r['state'],$mode);self::assertSame('uncertain',$r['replay_state'],$mode);self::assertTrue($r['replay_no_connection']);self::assertSame(1,$r['smtp_submissions'],$mode);}}
    public function testTwoWorkersAndCancellationShareThePhysicalOwnerLease():void {$r=$this->proof('concurrent');self::assertSame('accepted',$r['state']);self::assertSame([true,true],$r['contenders']);self::assertSame(1,$r['smtp_submissions']);}
    public function testLostAppendAcknowledgementCannotTriggerHordeBinaryRetryOrRepairReplay():void {$r=$this->proof('repair_lost');self::assertSame('uncertain',$r['copy_state']);self::assertSame(1,$r['copy_peer']['appends']);self::assertSame(0,$r['copy_peer']['searches']);self::assertTrue($r['copy_smtp_unchanged']);}
    public function testMalformedCopyProofAndOversizedLiteralRemainUncertainWithoutReplay():void {foreach(['repair_bad_literal','repair_bad_uid','repair_missing_uid'] as $scenario){$r=$this->proof($scenario);self::assertSame('uncertain',$r['copy_state'],$scenario);self::assertSame(1,$r['copy_peer']['appends'],$scenario);self::assertSame(0,$r['copy_peer']['searches'],$scenario);self::assertTrue($r['copy_smtp_unchanged']);}}
    public function testKilledBeforeCheckpointCanSubmitOnlyOnceAfterFreshDispatch():void {if(getenv('MCP_IT_DB')!=='pgsql')self::markTestSkipped('PostgreSQL kill fixture.');$r=$this->proof('kill_before');self::assertSame('queued',$r['state_after_kill']);self::assertSame('accepted',$r['state']);self::assertSame(1,$r['smtp_submissions']);}
    public function testKilledAfterDataAcceptanceBeforeDatabaseCommitCanNeverResubmit():void {if(getenv('MCP_IT_DB')!=='pgsql')self::markTestSkipped('PostgreSQL kill fixture.');$r=$this->proof('kill_after_data');self::assertTrue($r['kill_proof']['acceptance_persistence_blocked']);self::assertTrue($r['kill_proof']['server_accepted']);self::assertSame('uncertain',$r['state_after_kill']);self::assertSame('uncertain',$r['state']);self::assertSame(1,$r['smtp_submissions']);}
    public function testSentRepairCannotConstructSmtpOrAppendAgain():void {$r=$this->proof('repair');self::assertSame('verified',$r['copy_state']);self::assertTrue($r['copy_smtp_unchanged']);self::assertTrue($r['terminal_identity_released'],'Verified delivery must release account and alias administration.');}
    public function testCopyVerificationBindsActualSelectionAndRejectsGenerationChanges():void {foreach(['repair_selected_generation','repair_changed_during_fetch','repair_reconnect'] as $scenario){$r=$this->proof($scenario);self::assertSame('uncertain',$r['copy_state'],$scenario);self::assertSame(1,$r['copy_peer']['appends']);self::assertTrue($r['copy_smtp_unchanged']);if($scenario==='repair_selected_generation')self::assertSame(0,$r['copy_peer']['fetches']);}}
    public function testCopyReadbackSupportsUidAfterLiteralAndRefusesDuplicateTrailer():void {$r=$this->proof('repair_uid_after');self::assertSame('verified',$r['copy_state']);self::assertSame(1,$r['copy_peer']['appends']);self::assertSame(1,$r['copy_peer']['fetches']);self::assertTrue($r['copy_smtp_unchanged']);$r=$this->proof('repair_duplicate_uid');self::assertSame('uncertain',$r['copy_state']);self::assertSame(1,$r['copy_peer']['appends']);}

}
